#![allow(dead_code)]

//! Exact decimal expansion of an IEEE-754 `binary32` value.
//!
//! Every finite float is exactly `mantissa * 2^exp2`, which always has a *finite*
//! decimal expansion. Producing that expansion exactly is what lets
//! [`crate::cxx::ostream`] round the way `printf` does — including the
//! ties-to-even cases such as `57/128 == 0.4453125`, where knowing that nothing
//! follows the `5` is the whole game.
//!
//! Only what is needed for that is implemented: an unsigned big integer that can
//! be multiplied by a small factor and rendered in base 10.

/// Little-endian big integer in base 10^9. Base 10^9 is chosen so that rendering
/// to decimal is a straight per-limb zero-padded print with no division loop.
#[derive(Clone, Debug)]
pub struct BigUint {
    limbs: Vec<u32>,
}

const LIMB_BASE: u64 = 1_000_000_000;
const LIMB_DIGITS: usize = 9;

/// Largest power of five that keeps `limb * factor + carry` inside a `u64`.
const POW5_STEP: u32 = 12;
const POW5_STEP_VALUE: u32 = 244_140_625; // 5^12

/// Same idea for powers of two.
const POW2_STEP: u32 = 27;

impl BigUint {
    pub fn from_u32(v: u32) -> Self {
        let mut limbs = Vec::with_capacity(4);
        let mut v = v as u64;
        if v == 0 {
            limbs.push(0);
        }
        while v > 0 {
            limbs.push((v % LIMB_BASE) as u32);
            v /= LIMB_BASE;
        }
        BigUint { limbs }
    }

    pub fn is_zero(&self) -> bool {
        self.limbs.iter().all(|&l| l == 0)
    }

    /// `self *= factor`, where `factor <= 10^9` so the intermediate fits a `u64`.
    fn mul_small(&mut self, factor: u32) {
        debug_assert!(u64::from(factor) <= LIMB_BASE);
        let factor = u64::from(factor);
        let mut carry: u64 = 0;
        for limb in self.limbs.iter_mut() {
            let cur = u64::from(*limb) * factor + carry;
            *limb = (cur % LIMB_BASE) as u32;
            carry = cur / LIMB_BASE;
        }
        while carry > 0 {
            self.limbs.push((carry % LIMB_BASE) as u32);
            carry /= LIMB_BASE;
        }
    }

    /// `self *= 5^exp`.
    pub fn mul_pow5(&mut self, mut exp: u32) {
        while exp >= POW5_STEP {
            self.mul_small(POW5_STEP_VALUE);
            exp -= POW5_STEP;
        }
        if exp > 0 {
            self.mul_small(5u32.pow(exp));
        }
    }

    /// `self *= 2^exp`.
    pub fn mul_pow2(&mut self, mut exp: u32) {
        while exp >= POW2_STEP {
            self.mul_small(1u32 << POW2_STEP);
            exp -= POW2_STEP;
        }
        if exp > 0 {
            self.mul_small(1u32 << exp);
        }
    }

    /// Decimal digits, most significant first, without leading zeros.
    /// Zero renders as a single `0` digit.
    pub fn to_digits(&self) -> Vec<u8> {
        let top = match self.limbs.iter().rposition(|&l| l != 0) {
            Some(i) => i,
            None => return vec![0],
        };

        let mut out = Vec::with_capacity((top + 1) * LIMB_DIGITS);
        push_digits(&mut out, self.limbs[top], false);
        for i in (0..top).rev() {
            push_digits(&mut out, self.limbs[i], true);
        }
        out
    }
}

/// Append the digits of one base-10^9 limb, zero padded to 9 digits when it is
/// not the leading limb.
fn push_digits(out: &mut Vec<u8>, limb: u32, pad: bool) {
    let mut buf = [0u8; LIMB_DIGITS];
    let mut v = limb;
    for slot in buf.iter_mut().rev() {
        *slot = (v % 10) as u8;
        v /= 10;
    }
    let start = if pad {
        0
    } else {
        buf.iter().position(|&d| d != 0).unwrap_or(LIMB_DIGITS - 1)
    };
    out.extend_from_slice(&buf[start..]);
}

/// The class of a float, mirroring what `printf` has to distinguish.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FloatClass {
    Zero,
    Finite,
    Infinite,
    Nan,
}

/// A finite float written exactly as `0.d1 d2 d3 ... * 10^exp10`.
///
/// `digits` never has a leading zero and never has trailing zeros stripped, so
/// "is there anything after the digit I am about to drop?" is answerable exactly.
#[derive(Clone, Debug)]
pub struct ExactDecimal {
    pub digits: Vec<u8>,
    pub exp10: i32,
}

/// Sign, class, and (for finite non-zero values) the exact decimal expansion.
pub struct Decomposed {
    pub negative: bool,
    pub class: FloatClass,
    pub decimal: Option<ExactDecimal>,
}

/// Split a `f32` into sign / class / exact decimal expansion.
pub fn decompose_f32(value: f32) -> Decomposed {
    let bits = value.to_bits();
    let negative = bits >> 31 == 1;
    let biased_exp = ((bits >> 23) & 0xff) as i32;
    let fraction = bits & 0x007f_ffff;

    if biased_exp == 0xff {
        return Decomposed {
            negative,
            class: if fraction == 0 {
                FloatClass::Infinite
            } else {
                FloatClass::Nan
            },
            decimal: None,
        };
    }

    // Subnormals have no implicit leading bit and a fixed exponent.
    let (mut mantissa, mut exp2) = if biased_exp == 0 {
        (fraction, -149i32)
    } else {
        (fraction | 0x0080_0000, biased_exp - 127 - 23)
    };

    if mantissa == 0 {
        return Decomposed {
            negative,
            class: FloatClass::Zero,
            decimal: None,
        };
    }

    // Cancelling trailing zero bits keeps the big integers as small as possible;
    // it does not change the value.
    while mantissa & 1 == 0 {
        mantissa >>= 1;
        exp2 += 1;
    }

    // value == mantissa * 2^exp2. For exp2 < 0 use 2^-k == 5^k / 10^k so the
    // whole thing becomes an integer times a power of ten.
    let mut big = BigUint::from_u32(mantissa);
    let shift = if exp2 >= 0 {
        big.mul_pow2(exp2 as u32);
        0i32
    } else {
        let k = (-exp2) as u32;
        big.mul_pow5(k);
        k as i32
    };

    let digits = big.to_digits();
    let exp10 = digits.len() as i32 - shift;

    Decomposed {
        negative,
        class: FloatClass::Finite,
        decimal: Some(ExactDecimal { digits, exp10 }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn exact(value: f32) -> (String, i32) {
        let d = decompose_f32(value).decimal.expect("finite non-zero");
        (
            d.digits.iter().map(|&x| (b'0' + x) as char).collect(),
            d.exp10,
        )
    }

    #[test]
    fn big_multiplication_matches_known_powers() {
        let mut b = BigUint::from_u32(1);
        b.mul_pow5(13);
        assert_eq!(b.to_digits(), vec![1, 2, 2, 0, 7, 0, 3, 1, 2, 5]); // 5^13
        let mut b = BigUint::from_u32(3);
        b.mul_pow2(64);
        // 3 * 2^64 == 55340232221128654848
        assert_eq!(
            b.to_digits()
                .iter()
                .map(|&x| (b'0' + x) as char)
                .collect::<String>(),
            "55340232221128654848"
        );
    }

    #[test]
    fn expansion_is_exact_not_shortest() {
        // 57/128 is exact in binary and its decimal expansion terminates in a 5:
        // that is precisely the ties-to-even case printf has to resolve.
        assert_eq!(exact(57.0 / 128.0), ("4453125".to_string(), 0));
        assert_eq!(exact(11.0 / 16.0), ("6875".to_string(), 0));
        assert_eq!(exact(1.0), ("1".to_string(), 1));
        assert_eq!(exact(1024.0), ("1024".to_string(), 4));
        assert_eq!(exact(0.5), ("5".to_string(), 0));
    }

    #[test]
    fn smallest_subnormal_expands_fully() {
        // 2^-149, the smallest positive subnormal, has 149 significant digits.
        let (digits, exp10) = exact(f32::from_bits(1));
        assert_eq!(exp10, -44);
        assert!(digits.starts_with("140129846432481707"));
        assert_eq!(digits.len(), 105);
    }

    #[test]
    fn classes_are_reported() {
        assert_eq!(decompose_f32(0.0).class, FloatClass::Zero);
        assert!(decompose_f32(-0.0).negative);
        assert_eq!(decompose_f32(f32::INFINITY).class, FloatClass::Infinite);
        assert_eq!(decompose_f32(f32::NAN).class, FloatClass::Nan);
    }
}

