/// even digit.
///
/// Returns the kept digits (at most `p`, possibly fewer if the expansion was
/// shorter) and the possibly incremented decimal exponent.
fn round_to_significant_digits(exact: &ExactDecimal, p: usize) -> (Vec<u8>, i32) {
    let digits = &exact.digits;
    if digits.len() <= p {
        return (digits.clone(), exact.exp10);
    }

    let mut kept = digits[..p].to_vec();
    let first_dropped = digits[p];
    let rest_nonzero = digits[p + 1..].iter().any(|&d| d != 0);

    let round_up = match first_dropped.cmp(&5) {
        std::cmp::Ordering::Greater => true,
        std::cmp::Ordering::Less => false,
