//! Access to the raw `argv` bytes.
//!
//! The C++ program compares `argv[1]` with `"--a"` and feeds `argv[2]` to
//! `std::stoi`, both of which operate on bytes. `std::env::args()` panics on an
//! argument that is not valid UTF-8, which would be a visible difference from the
//! C++ binary, so the bytes are taken from `std::env::args_os()` instead. For
//! UTF-8 arguments — everything this program is ever invoked with — the two are
//! identical.

/// The command line as byte strings, `argv[0]` included, mirroring C++'s
/// `char* argv[]`.
pub fn argv_bytes() -> Vec<Vec<u8>> {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStrExt;
        std::env::args_os()
            .map(|arg| arg.as_os_str().as_bytes().to_vec())
            .collect()
    }
    #[cfg(not(unix))]
    {
        std::env::args_os()
            .map(|arg| arg.to_string_lossy().into_owned().into_bytes())
            .collect()
    }
}

