//! Hashing that matches what the C++ program got from `std::hash`.
//!
//! libstdc++ hashes integral types with the identity function
//! (`std::hash<int>{}(v) == static_cast<size_t>(v)`), so keeping that here keeps
//! the bucket layout — and therefore the hopscotch displacement and overflow
//! behaviour — identical to the original for integer keys.
//!
//! Other key types fall back to FNV-1a. That is not bit-identical to libstdc++
//! (which uses MurmurHash for strings), but nothing observable in this program
//! depends on it: the bucket count is driven purely by the load threshold.

use std::hash::{BuildHasherDefault, Hasher};

/// The hasher `HopscotchMap` uses by default.
pub type CxxBuildHasher = BuildHasherDefault<CxxHasher>;

#[derive(Default, Clone)]
pub struct CxxHasher {
    state: u64,
}

const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

impl Hasher for CxxHasher {
    fn finish(&self) -> u64 {
        self.state
    }

    fn write(&mut self, bytes: &[u8]) {
        let mut state = if self.state == 0 {
            FNV_OFFSET_BASIS
        } else {
            self.state
        };
        for &byte in bytes {
            state ^= u64::from(byte);
            state = state.wrapping_mul(FNV_PRIME);
        }
        self.state = state;
    }

    // std's `Hash` impls for integers route through these, which is what lets the
    // identity hash apply. Signed types sign-extend to `size_t`, matching the
    // `static_cast<size_t>` libstdc++ performs.
    fn write_u8(&mut self, i: u8) {
        self.state = u64::from(i);
    }
    fn write_u16(&mut self, i: u16) {
        self.state = u64::from(i);
    }
    fn write_u32(&mut self, i: u32) {
        self.state = u64::from(i);
    }
    fn write_u64(&mut self, i: u64) {
        self.state = i;
    }
    fn write_u128(&mut self, i: u128) {
        self.state = i as u64;
    }
    fn write_usize(&mut self, i: usize) {
        self.state = i as u64;
    }
    fn write_i8(&mut self, i: i8) {
        self.state = i as i64 as u64;
    }
    fn write_i16(&mut self, i: i16) {
        self.state = i as i64 as u64;
    }
    fn write_i32(&mut self, i: i32) {
        self.state = i as i64 as u64;
    }
    fn write_i64(&mut self, i: i64) {
        self.state = i as u64;
    }
    fn write_i128(&mut self, i: i128) {
        self.state = i as u64;
    }
    fn write_isize(&mut self, i: isize) {
        self.state = i as u64;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::{BuildHasher, Hash};

    fn hash_of<T: Hash>(value: T) -> u64 {
        let builder = CxxBuildHasher::default();
        let mut hasher = builder.build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        assert_eq!(hash_of(0i32), 0);
        assert_eq!(hash_of(11i32), 11);
        assert_eq!(hash_of(4096i32), 4096);
        // Negative ints sign-extend, like static_cast<size_t>(-1).
        assert_eq!(hash_of(-1i32), u64::MAX);
    }

    #[test]
    fn byte_keys_use_the_fallback() {
        assert_ne!(hash_of("a"), hash_of("b"));
        assert_eq!(hash_of("hopscotch"), hash_of("hopscotch"));
    }
}

