    }
    fn write_i32(&mut self, i: i32) {
        self.state = i as i64 as u64;
    }
    fn write_i64(&mut self, i: i64) {
        self.state = i as u64;
    }
    fn write_i128(&mut self, i: i128) {
        self.state = i as u64;
    }
    fn write_isize(&mut self, i: isize) {
        self.state = i as u64;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::{BuildHasher, Hash};

    fn hash_of<T: Hash>(value: T) -> u64 {
        let builder = CxxBuildHasher::default();
        let mut hasher = builder.build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        assert_eq!(hash_of(0i32), 0);
        assert_eq!(hash_of(11i32), 11);
        assert_eq!(hash_of(4096i32), 4096);
        // Negative ints sign-extend, like static_cast<size_t>(-1).
        assert_eq!(hash_of(-1i32), u64::MAX);
    }

    #[test]
    fn byte_keys_use_the_fallback() {
        assert_ne!(hash_of("a"), hash_of("b"));
        assert_eq!(hash_of("hopscotch"), hash_of("hopscotch"));
    }
}

