//! The hopscotch hash table.
//!
//! Each key has a home bucket. Its entry is stored somewhere in that bucket's
//! *neighborhood* — the [`NEIGHBORHOOD_SIZE`] slots starting at the home bucket —
//! and the home bucket carries a bitmap saying which of those slots hold its
//! entries. Lookups therefore only ever touch one cache-resident window.
//!
//! Two details of the C++ original that matter for observable behaviour:
//!
//! * The slot array is `bucket_count + NEIGHBORHOOD_SIZE - 1` long, so a
//!   neighborhood never wraps past the end and no modular arithmetic is needed.
//! * Anything that cannot be placed in its neighborhood, even after displacing
//!   other entries, goes to an overflow list. Overflowing does **not** trigger a
//!   resize; only the load threshold does. That is why the bucket count — and
//!   hence `load_factor()` — depends on nothing but the number of insertions.

use std::hash::{BuildHasher, Hash, Hasher};

use super::growth_policy::PowerOfTwoGrowthPolicy;

/// `NeighborhoodSize` in the C++ template's default arguments.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// `hopscotch_map`'s default `max_load_factor`.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.9;

/// Bit [`NEIGHBORHOOD_SIZE`] of the bitmap records "this bucket has entries in
/// the overflow list", so a lookup only scans the list when it must.
const OVERFLOW_BIT: u64 = 1u64 << NEIGHBORHOOD_SIZE;
const NEIGHBORHOOD_MASK: u64 = OVERFLOW_BIT - 1;

#[derive(Clone)]
struct Bucket<K, V> {
    /// Bit `i` set means the bucket `i` slots after this one holds an entry whose
    /// home bucket is this one.
    neighborhood: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Default for Bucket<K, V> {
    fn default() -> Self {
        Bucket {
            neighborhood: 0,
            entry: None,
        }
    }
}

pub struct HopscotchHash<K, V, S = super::hash::CxxBuildHasher> {
    buckets: Vec<Bucket<K, V>>,
    overflow: Vec<(K, V)>,
    bucket_count: usize,
    nb_elements: usize,
    max_load_factor: f32,
    load_threshold: usize,
    policy: PowerOfTwoGrowthPolicy,
    hash_builder: S,
}

impl<K, V, S> HopscotchHash<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_hasher(bucket_count: usize, hash_builder: S) -> Self {
        let (policy, bucket_count) = PowerOfTwoGrowthPolicy::new(bucket_count);
        let mut table = HopscotchHash {
            buckets: Vec::new(),
            overflow: Vec::new(),
            bucket_count,
            nb_elements: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: 0,
            policy,
            hash_builder,
        };
        table.allocate_buckets();
        table.load_threshold = compute_load_threshold(bucket_count, table.max_load_factor);
        table
    }

    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, or none at all when there
    /// are no buckets.
    fn allocate_buckets(&mut self) {
        self.buckets.clear();
        if self.bucket_count > 0 {
            self.buckets
                .resize_with(self.bucket_count + NEIGHBORHOOD_SIZE - 1, Bucket::default);
        }
    }

    pub fn len(&self) -> usize {
        self.nb_elements
    }

    pub fn is_empty(&self) -> bool {
        self.nb_elements == 0
    }

    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn overflow_len(&self) -> usize {
        self.overflow.len()
    }

    /// `size() / bucket_count()`, computed in `float` like the C++ original, and
    /// defined as 0 for an empty table rather than dividing by zero.
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            return 0.0;
        }
        self.nb_elements as f32 / self.bucket_count as f32
    }

    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Set the maximum load factor and recompute the growth threshold. The
    /// bucket count is left alone; only a later `rehash`/insert reacts to it.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        self.max_load_factor = max_load_factor;
        self.load_threshold = compute_load_threshold(self.bucket_count, max_load_factor);
    }

    fn hash_key(&self, key: &K) -> u64 {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Insert if the key is absent. Returns whether anything was inserted, which
    /// is the `bool` half of C++'s `insert` return value.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        let hash = self.hash_key(&key);
        if self.contains(&key, hash) {
            return false;
        }
        // The threshold is consulted only for genuinely new elements, and the
        // home bucket is recomputed afterwards because growing changes the mask.
        if self.nb_elements >= self.load_threshold {
            self.rehash_impl(self.policy.next_bucket_count());
        }
        self.insert_new(hash, key, value);
        true
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        let hash = self.hash_key(key);
        let ibucket = self.policy.bucket_for_hash(hash);
        if self.bucket_count == 0 {
            return None;
        }

        let neighborhood = self.buckets[ibucket].neighborhood;
        let mut bits = neighborhood & NEIGHBORHOOD_MASK;
        while bits != 0 {
            let offset = bits.trailing_zeros() as usize;
            bits &= bits - 1;
            if let Some((k, v)) = &self.buckets[ibucket + offset].entry {
                if k == key {
                    return Some(v);
                }
            }
        }

        if neighborhood & OVERFLOW_BIT != 0 {
            for (k, v) in &self.overflow {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.get(key).is_some()
    }

    fn contains(&self, key: &K, _hash: u64) -> bool {
        self.get(key).is_some()
    }

    /// Place a key known to be absent, growing nothing.
    fn insert_new(&mut self, hash: u64, key: K, value: V) {
        debug_assert!(self.bucket_count > 0, "threshold forces buckets to exist");
        let ibucket = self.policy.bucket_for_hash(hash);

        if let Some(mut islot) = self.first_empty_slot_from(ibucket) {
            // Too far away to be in the neighborhood: drag the hole closer by
            // moving an entry that is allowed to sit further out.
            while islot - ibucket >= NEIGHBORHOOD_SIZE {
                match self.swap_empty_slot_closer(islot) {
                    Some(closer) => islot = closer,
                    None => break,
                }
            }

            if islot - ibucket < NEIGHBORHOOD_SIZE {
                self.buckets[islot].entry = Some((key, value));
                self.buckets[ibucket].neighborhood |= 1u64 << (islot - ibucket);
                self.nb_elements += 1;
                return;
            }
        }

        self.overflow.push((key, value));
        self.buckets[ibucket].neighborhood |= OVERFLOW_BIT;
        self.nb_elements += 1;
    }

    fn first_empty_slot_from(&self, start: usize) -> Option<usize> {
        (start..self.buckets.len()).find(|&i| self.buckets[i].entry.is_none())
    }

    /// Move some entry into the empty slot at `islot` so the hole ends up closer
    /// to the front, and return the hole's new index.
    ///
    /// Only an entry whose home bucket is within `NEIGHBORHOOD_SIZE - 1` of
    /// `islot` may move there, so candidates are scanned from the earliest such
    /// home bucket forwards, which moves the hole as far back as possible.
    fn swap_empty_slot_closer(&mut self, islot: usize) -> Option<usize> {
        let first_candidate = islot + 1 - NEIGHBORHOOD_SIZE;
        for home in first_candidate..islot {
            let movable = self.buckets[home].neighborhood & NEIGHBORHOOD_MASK;
            if movable == 0 {
                continue;
            }
            // The lowest set bit is the entry closest to `home`, i.e. the one
            // whose displacement costs the least.
            let offset = movable.trailing_zeros() as usize;
            let from = home + offset;
            if from >= islot {
                continue;
            }

            self.buckets[islot].entry = self.buckets[from].entry.take();
            self.buckets[home].neighborhood &= !(1u64 << offset);
            self.buckets[home].neighborhood |= 1u64 << (islot - home);
            return Some(from);
        }
        None
    }

    /// Grow or shrink to at least `min_bucket_count` buckets, honouring the
    /// current `max_load_factor`. `rehash(0)` therefore sizes the table to the
    /// smallest power of two that can hold the current elements.
    pub fn rehash(&mut self, min_bucket_count: usize) {
        let required = required_bucket_count(self.nb_elements, self.max_load_factor);
        self.rehash_impl(min_bucket_count.max(required));
    }

    /// Reserve room for `count` elements without changing `max_load_factor`.
    pub fn reserve(&mut self, count: usize) {
        self.rehash(required_bucket_count(count, self.max_load_factor));
    }

    fn rehash_impl(&mut self, min_bucket_count: usize) {
        let (policy, bucket_count) = PowerOfTwoGrowthPolicy::new(min_bucket_count);

        let old_buckets = std::mem::take(&mut self.buckets);
        let old_overflow = std::mem::take(&mut self.overflow);

        self.policy = policy;
        self.bucket_count = bucket_count;
        self.nb_elements = 0;
        self.load_threshold = compute_load_threshold(bucket_count, self.max_load_factor);
        self.allocate_buckets();

        let entries = old_buckets
            .into_iter()
            .filter_map(|bucket| bucket.entry)
            .chain(old_overflow);

        if bucket_count == 0 {
            // Only reachable with nothing to move: rehash(0) on an empty table.
            debug_assert_eq!(entries.count(), 0);
            return;
        }

        for (key, value) in entries {
            let hash = self.hash_key(&key);
            self.insert_new(hash, key, value);
        }
    }

    /// Every element, for tests and iteration. Order is unspecified, as in C++.
    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
        self.buckets
            .iter()
            .filter_map(|bucket| bucket.entry.as_ref())
            .chain(self.overflow.iter())
            .map(|(k, v)| (k, v))
    }
}

/// `size_type(float(bucket_count) * max_load_factor)` — a C cast, so it truncates.
fn compute_load_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    (bucket_count as f32 * max_load_factor) as usize
}

/// `ceil(float(count) / max_load_factor)`, the bucket count needed to hold
/// `count` elements without exceeding the load factor.
fn required_bucket_count(count: usize, max_load_factor: f32) -> usize {
    if count == 0 {
        return 0;
    }
    (count as f32 / max_load_factor).ceil() as usize
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tsl::hash::CxxBuildHasher;

    fn table() -> HopscotchHash<i32, i32> {
        HopscotchHash::with_hasher(0, CxxBuildHasher::default())
    }

    fn fill(count: i32) -> HopscotchHash<i32, i32> {
        let mut t = table();
        for i in 0..count {
            t.insert(i, i * 9);
        }
        t
    }

    #[test]
    fn thresholds_truncate_the_float_product() {
        // These are the values the C++ binary's growth boundaries imply.
        assert_eq!(compute_load_threshold(0, DEFAULT_MAX_LOAD_FACTOR), 0);
        assert_eq!(compute_load_threshold(2, DEFAULT_MAX_LOAD_FACTOR), 1);
        assert_eq!(compute_load_threshold(4, DEFAULT_MAX_LOAD_FACTOR), 3);
        assert_eq!(compute_load_threshold(8, DEFAULT_MAX_LOAD_FACTOR), 7);
        assert_eq!(compute_load_threshold(16, DEFAULT_MAX_LOAD_FACTOR), 14);
        assert_eq!(compute_load_threshold(32, DEFAULT_MAX_LOAD_FACTOR), 28);
        assert_eq!(compute_load_threshold(64, DEFAULT_MAX_LOAD_FACTOR), 57);
        assert_eq!(compute_load_threshold(128, DEFAULT_MAX_LOAD_FACTOR), 115);
        assert_eq!(compute_load_threshold(256, DEFAULT_MAX_LOAD_FACTOR), 230);
    }

    #[test]
    fn bucket_counts_follow_the_growth_boundaries() {
        // Boundary pairs read off the reference binary: the last count that fits
        // and the first that forces a doubling.
        let cases = [
            (0, 0),
            (1, 2),
            (2, 4),
            (3, 4),
            (4, 8),
            (7, 8),
            (8, 16),
            (14, 16),
            (15, 32),
            (28, 32),
            (29, 64),
            (57, 64),
            (58, 128),
            (115, 128),
            (116, 256),
            (230, 256),
            (231, 512),
        ];
        for (count, expected) in cases {
            assert_eq!(fill(count).bucket_count(), expected, "count = {count}");
        }
    }

    #[test]
    fn every_key_is_findable_and_unique() {
        let mut t = fill(500);
        assert_eq!(t.len(), 500);
        for i in 0..500 {
            assert_eq!(t.get(&i), Some(&(i * 9)));
        }
        assert_eq!(t.get(&500), None);
        assert_eq!(t.get(&-1), None);
        // Re-inserting an existing key changes nothing.
        assert!(!t.insert(0, 12345));
        assert_eq!(t.len(), 500);
        assert_eq!(t.get(&0), Some(&0));
    }

    #[test]
    fn rehash_zero_sizes_to_the_current_load_factor() {
        let mut t = fill(11);
        assert_eq!(t.bucket_count(), 16);
        t.set_max_load_factor(0.5);
        t.rehash(0);
        // ceil(11 / 0.5) == 22, rounded up to 32.
        assert_eq!(t.bucket_count(), 32);
        assert_eq!(t.len(), 11);
        for i in 0..11 {
            assert_eq!(t.get(&i), Some(&(i * 9)));
        }
    }

    #[test]
    fn rehash_can_shrink() {
        let mut t = fill(11);
        t.rehash(1024);
        assert_eq!(t.bucket_count(), 1024);
        // With the default 0.9 factor, 11 elements need only ceil(11/0.9) == 13
        // buckets, i.e. 16.
        t.rehash(0);
        assert_eq!(t.bucket_count(), 16);
        assert_eq!(t.len(), 11);
    }

    #[test]
    fn an_empty_table_has_no_load_factor_to_speak_of() {
        let mut t = table();
        assert_eq!(t.bucket_count(), 0);
        assert_eq!(t.load_factor(), 0.0);
        t.rehash(0);
        assert_eq!(t.bucket_count(), 0);
        assert_eq!(t.load_factor(), 0.0);
    }

    #[test]
    fn keys_that_collide_hard_still_all_land() {
        // Identity hashing plus a stride of the bucket count sends every key to
        // the same home bucket, which is what exercises displacement and the
        // overflow list.
        let mut t = HopscotchHash::<i32, i32>::with_hasher(64, CxxBuildHasher::default());
        for i in 0..40 {
            assert!(t.insert(i * 64, i));
        }
        assert_eq!(t.len(), 40);
        for i in 0..40 {
            assert_eq!(t.get(&(i * 64)), Some(&i), "key {}", i * 64);
        }
    }

    #[test]
    fn overflow_survives_a_rehash() {
        let mut t = HopscotchHash::<i32, i32>::with_hasher(2, CxxBuildHasher::default());
        // 200 keys all hashing to bucket 0 cannot fit a 62-slot neighborhood.
        for i in 0..200 {
            t.insert(i * 1024, i);
        }
        assert!(t.overflow_len() > 0);
        t.rehash(4096);
        for i in 0..200 {
            assert_eq!(t.get(&(i * 1024)), Some(&i));
        }
        assert_eq!(t.len(), 200);
    }
}

