        for i in 0..200 {
            assert!(t.insert(i * 1024, i));
        }
        assert!(t.overflow_len() > 0);
        t.rehash(4096);
        for i in 0..200 {
            assert_eq!(t.get(&(i * 1024)), Some(&i));
        }
        assert_eq!(t.len(), 200);
    }
}

