        t
    }

    #[test]
    fn thresholds_truncate_the_float_product() {
        // These are the values the reference binary's growth boundaries imply.
        assert_eq!(compute_load_threshold(0, DEFAULT_MAX_LOAD_FACTOR), 0);
        assert_eq!(compute_load_threshold(2, DEFAULT_MAX_LOAD_FACTOR), 1);
        assert_eq!(compute_load_threshold(4, DEFAULT_MAX_LOAD_FACTOR), 3);
        assert_eq!(compute_load_threshold(8, DEFAULT_MAX_LOAD_FACTOR), 7);
        assert_eq!(compute_load_threshold(16, DEFAULT_MAX_LOAD_FACTOR), 14);
        assert_eq!(compute_load_threshold(32, DEFAULT_MAX_LOAD_FACTOR), 28);
        assert_eq!(compute_load_threshold(64, DEFAULT_MAX_LOAD_FACTOR), 57);
        assert_eq!(compute_load_threshold(128, DEFAULT_MAX_LOAD_FACTOR), 115);
        assert_eq!(compute_load_threshold(256, DEFAULT_MAX_LOAD_FACTOR), 230);
    }

    #[test]
    fn bucket_counts_follow_the_growth_boundaries() {
        // Boundary pairs read off the reference binary: the last count that fits
        // and the first that forces a doubling.
        let cases = [
