            (14, 16),
            (15, 32),
            (28, 32),
            (29, 64),
            (57, 64),
            (58, 128),
            (115, 128),
            (116, 256),
            (230, 256),
            (231, 512),
        ];
        for (count, expected) in cases {
            assert_eq!(fill(count).bucket_count(), expected, "count = {count}");
        }
    }

    #[test]
    fn every_key_is_findable_and_unique() {
        let mut t = fill(500);
        assert_eq!(t.len(), 500);
        for i in 0..500 {
            assert_eq!(t.get(&i), Some(&(i * 9)));
