//! `tsl::hopscotch_map`.
//!
//! A thin facade over [`HopscotchHash`] exposing the pieces of the C++ API the
//! test uses. C++ overloads `max_load_factor` as both getter and setter; Rust
//! cannot, so the setter is spelled [`HopscotchMap::set_max_load_factor`].

use std::hash::{BuildHasher, Hash};

use super::hash::CxxBuildHasher;
use super::hopscotch_hash::HopscotchHash;

pub struct HopscotchMap<K, V, S = CxxBuildHasher> {
    table: HopscotchHash<K, V, S>,
}

impl<K, V> HopscotchMap<K, V, CxxBuildHasher>
where
    K: Hash + Eq,
{
    /// A default-constructed map, which starts with no buckets at all — the first
    /// insert is what allocates them.
    pub fn new() -> Self {
        Self::with_capacity(0)
    }

    /// A map sized for at least `bucket_count` buckets.
    pub fn with_capacity(bucket_count: usize) -> Self {
        HopscotchMap {
            table: HopscotchHash::with_hasher(bucket_count, CxxBuildHasher::default()),
        }
    }
}

impl<K, V> Default for HopscotchMap<K, V, CxxBuildHasher>
where
    K: Hash + Eq,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_capacity_and_hasher(bucket_count: usize, hash_builder: S) -> Self {
        HopscotchMap {
            table: HopscotchHash::with_hasher(bucket_count, hash_builder),
        }
    }

    /// Insert a key/value pair, leaving an existing entry for that key alone.
    /// Returns whether the pair was inserted, mirroring the `bool` in C++'s
    /// `std::pair<iterator, bool>`.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        self.table.insert(key, value)
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        self.table.get(key)
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.table.contains_key(key)
    }

    /// `size()`.
    pub fn len(&self) -> usize {
        self.table.len()
    }

    pub fn is_empty(&self) -> bool {
        self.table.is_empty()
    }

    pub fn bucket_count(&self) -> usize {
        self.table.bucket_count()
    }

    pub fn load_factor(&self) -> f32 {
        self.table.load_factor()
    }

    pub fn max_load_factor(&self) -> f32 {
        self.table.max_load_factor()
    }

    /// The setter half of C++'s overloaded `max_load_factor`.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        self.table.set_max_load_factor(max_load_factor);
    }

    pub fn rehash(&mut self, bucket_count: usize) {
        self.table.rehash(bucket_count);
    }

    pub fn reserve(&mut self, count: usize) {
        self.table.reserve(count);
    }

    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
        self.table.iter()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_fresh_map_is_empty_and_bucketless() {
        let map: HopscotchMap<i32, i32> = HopscotchMap::new();
        assert!(map.is_empty());
        assert_eq!(map.len(), 0);
        assert_eq!(map.bucket_count(), 0);
        assert_eq!(map.load_factor(), 0.0);
        assert_eq!(map.max_load_factor(), 0.9);
    }

    #[test]
    fn it_reproduces_the_test_programs_arithmetic() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..11 {
            assert!(map.insert(i, i * 9));
        }
        assert_eq!(map.len(), 11);
        assert_eq!(map.bucket_count(), 16);
        assert_eq!(map.load_factor(), 11.0 / 16.0);

        map.set_max_load_factor(0.5);
        map.rehash(0);
        assert_eq!(map.bucket_count(), 32);
        assert_eq!(map.load_factor(), 11.0 / 32.0);
    }

    #[test]
    fn duplicate_keys_are_rejected() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        assert!(map.insert(7, 63));
        assert!(!map.insert(7, 999));
        assert_eq!(map.len(), 1);
        assert_eq!(map.get(&7), Some(&63));
    }

    #[test]
    fn it_works_with_non_integer_keys() {
        let mut map: HopscotchMap<String, usize> = HopscotchMap::new();
        for (i, word) in "the quick brown fox jumps over the lazy dog"
            .split(' ')
            .enumerate()
        {
            map.insert(word.to_string(), i);
        }
        assert_eq!(map.len(), 8); // "the" appears twice
        assert_eq!(map.get(&"quick".to_string()), Some(&1));
        assert_eq!(map.get(&"the".to_string()), Some(&0));
        assert!(!map.contains_key(&"cat".to_string()));
    }

    #[test]
    fn iteration_visits_everything_once() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..300 {
            map.insert(i, i * 9);
        }
        let mut seen: Vec<(i32, i32)> = map.iter().map(|(&k, &v)| (k, v)).collect();
        seen.sort_unstable();
        assert_eq!(seen.len(), 300);
        for (i, &(k, v)) in seen.iter().enumerate() {
            assert_eq!(k, i as i32);
            assert_eq!(v, k * 9);
        }
    }
}

