//! Port of `tests/test11.cpp` from the hopscotch-map test suite.
//!
//! The original, verbatim:
//!
//! ```cpp
//! int main(int argc, char* argv[]) {
//!     int count = 11;
//!     if (argc > 1 && std::string(argv[1]) == "--a") {
//!         count = std::stoi(argv[2]);
//!     }
//!
//!     tsl::hopscotch_map<int, int> map;
//!     for (int i = 0; i < count; i++) {
//!         map.insert({i, i * 9});
//!     }
//!
//!     std::cout << map.load_factor() << " ";
//!     map.max_load_factor(0.5);
//!     map.rehash(0);
//!     std::cout << map.load_factor() << std::endl;
//!
//!     return 0;
//! }
//! ```
//!
//! What the program actually measures is the container's bucket-count policy.
//! `map` starts with no buckets; inserting element number `size + 1` first checks
//! `size >= trunc(bucket_count * max_load_factor)` and, if so, doubles the bucket
//! count (from zero it jumps straight to two). With the default `max_load_factor`
//! of `0.9f` that gives thresholds of 0, 1, 3, 7, 14, 28, 57, 115, 230, ... so the
//! first printed load factor lands anywhere in roughly `[0.45, 0.9]`. Dropping
//! `max_load_factor` to 0.5 and calling `rehash(0)` then resizes to
//! `ceil(size / 0.5)` rounded up to a power of two, which is why the second value
//! is always at most 0.5.
//!
//! See [`tsl`] for the container and [`cxx`] for the C++ runtime behaviour
//! (`printf("%g")` formatting, `std::stoi`, and the uncaught-exception abort path)
//! that the byte-for-byte output depends on.

mod cxx;
mod tsl;

use cxx::{argv, ostream, stoi, terminate};
use tsl::HopscotchMap;

/// The flag that switches the element count away from its default.
const COUNT_FLAG: &[u8] = b"--a";

/// The default element count, as in the C++ source.
const DEFAULT_COUNT: i32 = 11;

/// `map.max_load_factor(0.5)`.
const REDUCED_MAX_LOAD_FACTOR: f32 = 0.5;

fn main() {
    let argv = argv::argv_bytes();
    let count = parse_count(&argv);
    println!("{}", run(count));
}

/// Resolve the element count from the command line.
///
/// Any failure here is a C++ exception escaping `main`, which does not return: it
/// prints libstdc++'s terminate message and aborts.
fn parse_count(argv: &[Vec<u8>]) -> i32 {
    if argv.len() <= 1 || argv[1].as_slice() != COUNT_FLAG {
        return DEFAULT_COUNT;
    }

    match argv.get(2) {
        Some(text) => match stoi::stoi(text) {
            Ok(count) => count,
            Err(error) => {
                terminate::terminate_after_uncaught_exception(error.exception_type(), error.what())
            }
        },
        // With only "--a" on the command line, `argv[2]` is the NULL that
        // terminates the argv array, and `std::string(nullptr)` throws.
        None => terminate::terminate_after_uncaught_exception(
            "std::logic_error",
            "basic_string::_S_construct null not valid",
        ),
    }
}

/// Build the program's single line of output: the load factor after `count`
/// insertions, then the load factor after tightening `max_load_factor` to 0.5 and
/// rehashing.
fn run(count: i32) -> String {
    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    for i in 0..count {
        // `i * 9` overflows for counts past ~2.4e8, which is undefined in C++ but
        // wraps in practice on every real compiler.
        map.insert(i, i.wrapping_mul(9));
    }

    let before = ostream::to_string_f32(map.load_factor());
    map.set_max_load_factor(REDUCED_MAX_LOAD_FACTOR);
    map.rehash(0);
    let after = ostream::to_string_f32(map.load_factor());

    format!("{before} {after}")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(items: &[&str]) -> Vec<Vec<u8>> {
        std::iter::once("test11")
            .chain(items.iter().copied())
            .map(|s| s.as_bytes().to_vec())
            .collect()
    }

    #[test]
    fn documented_examples() {
        // The five examples recorded in the C++ source.
        assert_eq!(run(parse_count(&args(&[]))), "0.6875 0.34375");
        assert_eq!(run(parse_count(&args(&["--b"]))), "0.6875 0.34375");
        assert_eq!(run(parse_count(&args(&["--A"]))), "0.6875 0.34375");
        assert_eq!(run(parse_count(&args(&["--a", "0"]))), "0 0");
        assert_eq!(run(parse_count(&args(&["--a", "1"]))), "0.5 0.5");
    }

    #[test]
    fn only_an_exact_flag_match_counts() {
        for other in ["--b", "--A", "-a", "", "--a=5", "--a ", " --a", "--aa"] {
            assert_eq!(parse_count(&args(&[other])), DEFAULT_COUNT, "arg {other:?}");
        }
        assert_eq!(parse_count(&args(&[])), DEFAULT_COUNT);
        // A non-matching argv[1] means argv[2] is never even looked at.
        assert_eq!(parse_count(&args(&["--b", "abc"])), DEFAULT_COUNT);
        // Extra arguments after the count are ignored.
        assert_eq!(parse_count(&args(&["--a", "15", "extra"])), 15);
    }

    #[test]
    fn counts_are_parsed_like_stoi() {
        assert_eq!(parse_count(&args(&["--a", "007"])), 7);
        assert_eq!(parse_count(&args(&["--a", " 12"])), 12);
        assert_eq!(parse_count(&args(&["--a", "12abc"])), 12);
        assert_eq!(parse_count(&args(&["--a", "3.9"])), 3);
        assert_eq!(parse_count(&args(&["--a", "+7"])), 7);
        assert_eq!(parse_count(&args(&["--a", "0x10"])), 0);
        assert_eq!(parse_count(&args(&["--a", "-5"])), -5);
    }

    #[test]
    fn a_negative_count_inserts_nothing() {
        assert_eq!(run(-5), "0 0");
        assert_eq!(run(i32::MIN), "0 0");
    }

    #[test]
    fn growth_boundaries_seen_from_the_outside() {
        // Each pair straddles a doubling of the bucket count.
        assert_eq!(run(14), "0.875 0.4375");
        assert_eq!(run(15), "0.46875 0.46875");
        assert_eq!(run(57), "0.890625 0.445312");
        assert_eq!(run(58), "0.453125 0.453125");
        assert_eq!(run(115), "0.898438 0.449219");
        assert_eq!(run(116), "0.453125 0.453125");
        assert_eq!(run(230), "0.898438 0.449219");
        assert_eq!(run(231), "0.451172 0.451172");
    }

    #[test]
    fn larger_counts() {
        assert_eq!(run(1000), "0.488281 0.488281");
        assert_eq!(run(1024), "0.5 0.5");
        assert_eq!(run(1025), "0.500488 0.250244");
        assert_eq!(run(10000), "0.610352 0.305176");
    }
}

