#![allow(dead_code)]

//! Hashing that matches what the C++ program got from `std::hash`.
//!
//! libstdc++ hashes integral types with the identity function
//! (`std::hash<int>{}(v) == static_cast<size_t>(v)`), so keeping that here keeps
//! the bucket layout — and therefore the hopscotch displacement and overflow
//! behaviour — identical to the original for integer keys.
//!
//! Everything else falls back to FNV-1a. That is not bit-identical to libstdc++
//! (which uses MurmurHash for strings), but nothing observable in this program
//! depends on it: the bucket count is driven purely by the load threshold.

use std::hash::{BuildHasherDefault, Hasher};

/// The hasher [`crate::tsl::HopscotchMap`] uses by default.
pub type CxxBuildHasher = BuildHasherDefault<CxxHasher>;

/// What has been fed to the hasher so far.
///
/// The distinction matters because the identity hash is only correct for a key
/// that is *exactly one* integer. `str`, for instance, hashes as its bytes
/// followed by `write_u8(0xff)`, and treating that trailing byte as an identity
/// hash would throw the string's bytes away entirely.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Empty,
    /// A single integer and nothing else: `state` is that integer.
    Integral,
    /// An FNV-1a accumulation.
    Mixed,
}

#[derive(Clone)]
pub struct CxxHasher {
    state: u64,
    kind: Kind,
}

const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

impl Default for CxxHasher {
    fn default() -> Self {
        CxxHasher {
            state: 0,
            kind: Kind::Empty,
        }
    }
}

impl CxxHasher {
    /// A lone integer key hashes to itself; anything after it degrades to FNV-1a.
    fn write_integral(&mut self, widened: u64) {
        match self.kind {
            Kind::Empty => {
                self.state = widened;
                self.kind = Kind::Integral;
            }
            _ => {
                self.ensure_mixed();
                self.fnv(&widened.to_le_bytes());
            }
        }
    }

    /// Switch to FNV-1a, folding in whatever integer was already there.
    fn ensure_mixed(&mut self) {
        if self.kind == Kind::Mixed {
            return;
        }
        let previous = std::mem::replace(&mut self.state, FNV_OFFSET_BASIS);
        let had_integer = self.kind == Kind::Integral;
        self.kind = Kind::Mixed;
        if had_integer {
            self.fnv(&previous.to_le_bytes());
        }
    }

    fn fnv(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.state ^= u64::from(byte);
            self.state = self.state.wrapping_mul(FNV_PRIME);
        }
    }
}

impl Hasher for CxxHasher {
    fn finish(&self) -> u64 {
        self.state
    }

    fn write(&mut self, bytes: &[u8]) {
        self.ensure_mixed();
        self.fnv(bytes);
    }

    // std's `Hash` impls for integers route through these, which is what lets the
    // identity hash apply. Signed types sign-extend, matching the
    // `static_cast<size_t>` libstdc++ performs.
    fn write_u8(&mut self, i: u8) {
        self.write_integral(u64::from(i));
    }
    fn write_u16(&mut self, i: u16) {
        self.write_integral(u64::from(i));
    }
    fn write_u32(&mut self, i: u32) {
        self.write_integral(u64::from(i));
    }
    fn write_u64(&mut self, i: u64) {
        self.write_integral(i);
    }
    fn write_usize(&mut self, i: usize) {
        self.write_integral(i as u64);
    }
    fn write_i8(&mut self, i: i8) {
        self.write_integral(i as i64 as u64);
    }
    fn write_i16(&mut self, i: i16) {
        self.write_integral(i as i64 as u64);
    }
    fn write_i32(&mut self, i: i32) {
        self.write_integral(i as i64 as u64);
    }
    fn write_i64(&mut self, i: i64) {
        self.write_integral(i as u64);
    }
    fn write_isize(&mut self, i: isize) {
        self.write_integral(i as u64);
    }
    // 128-bit values do not fit the identity path, so they always mix.
    fn write_u128(&mut self, i: u128) {
        self.ensure_mixed();
        self.fnv(&i.to_le_bytes());
    }
    fn write_i128(&mut self, i: i128) {
        self.ensure_mixed();
        self.fnv(&i.to_le_bytes());
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;
    use std::hash::{BuildHasher, Hash};

    fn hash_of<T: Hash>(value: T) -> u64 {
        let mut hasher = CxxBuildHasher::default().build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        assert_eq!(hash_of(0i32), 0);
        assert_eq!(hash_of(11i32), 11);
        assert_eq!(hash_of(4096i32), 4096);
        assert_eq!(hash_of(123u64), 123);
        // Negative ints sign-extend, like static_cast<size_t>(-1).
        assert_eq!(hash_of(-1i32), u64::MAX);
    }

    #[test]
    fn strings_do_not_collapse_onto_their_terminator() {
        // `Hash for str` writes the bytes and then write_u8(0xff); the terminator
        // must not wipe out the bytes that came before it.
        assert_ne!(hash_of("a"), hash_of("b"));
        assert_ne!(hash_of("a"), 0xff);
