use std::hash::{BuildHasherDefault, Hasher};

/// The hasher [`crate::tsl::HopscotchMap`] uses by default.
pub type CxxBuildHasher = BuildHasherDefault<CxxHasher>;

/// What has been fed to the hasher so far.
///
/// The distinction matters because the identity hash is only correct for a key
/// that is *exactly one* integer. `str`, for instance, hashes as its bytes
/// followed by `write_u8(0xff)`, and treating that trailing byte as an identity
/// hash would throw the string's bytes away entirely.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Empty,
    /// A single integer and nothing else: `state` is that integer.
    Integral,
    /// An FNV-1a accumulation.
    Mixed,
}

#[derive(Clone)]
pub struct CxxHasher {
    state: u64,
    kind: Kind,
}

const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

impl Default for CxxHasher {
    fn default() -> Self {
        CxxHasher {
            state: 0,
            kind: Kind::Empty,
        }
    }
}

impl CxxHasher {
    /// A lone integer key hashes to itself; anything after it degrades to FNV-1a.
    fn write_integral(&mut self, widened: u64) {
        match self.kind {
            Kind::Empty => {
                self.state = widened;
                self.kind = Kind::Integral;
            }
            _ => {
                self.ensure_mixed();
                self.fnv(&widened.to_le_bytes());
            }
        }
    }

    /// Switch to FNV-1a, folding in whatever integer was already there.
    fn ensure_mixed(&mut self) {
        if self.kind == Kind::Mixed {
            return;
        }
        let previous = std::mem::replace(&mut self.state, FNV_OFFSET_BASIS);
        let had_integer = self.kind == Kind::Integral;
        self.kind = Kind::Mixed;
        if had_integer {
            self.fnv(&previous.to_le_bytes());
        }
    }

    fn fnv(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.state ^= u64::from(byte);
            self.state = self.state.wrapping_mul(FNV_PRIME);
        }
    }
}

