//! Differential checker: replay a `%g` corpus produced by `gen_corpus.c` through
//! the Rust formatter and report any disagreement with glibc.
//!
//!   gcc -O2 -o gen_corpus tools/gen_corpus.c && ./gen_corpus > /tmp/gcorpus.tsv
//!   rustc --edition 2021 -O tools/check_g.rs -o check_g && ./check_g /tmp/gcorpus.tsv

#[path = "../cxx/mod.rs"]
mod cxx;

use std::io::{BufRead, BufReader};

fn main() {
    let path = std::env::args()
        .nth(1)
        .expect("usage: check_g <corpus.tsv> [precision]");
    let precision: usize = std::env::args()
        .nth(2)
        .map_or(cxx::ostream::DEFAULT_PRECISION, |p| p.parse().unwrap());

    let file = std::fs::File::open(&path).expect("corpus is readable");
    let mut checked = 0u64;
    let mut failures = 0u64;

    for line in BufReader::new(file).lines() {
        let line = line.expect("corpus line");
        let (bits, expected) = match line.split_once('\t') {
            Some(parts) => parts,
            None => continue,
        };
        let value = f32::from_bits(u32::from_str_radix(bits, 16).expect("hex bits"));
        let actual = cxx::ostream::format_g(value, precision);
        checked += 1;
        if actual != expected {
            failures += 1;
            if failures <= 25 {
                println!("MISMATCH bits={bits} glibc={expected:?} rust={actual:?}");
            }
        }
    }

    println!("checked {checked} values at precision {precision}, {failures} mismatches");
    if failures > 0 {
        std::process::exit(1);
    }
}

