 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <float.h>

static void emit(float f) {
    uint32_t bits;
    memcpy(&bits, &f, sizeof bits);
    printf("%08x\t%g\n", bits, (double)f);
}

int main(void) {
    /* 1. Every value a load factor can be: n / 2^k. These are exact binary
     *    fractions, so their decimal expansions terminate and land on printf's
     *    ties-to-even path far more often than random values do. */
    for (int k = 1; k <= 24; k++) {
        long denom = 1L << k;
        long limit = denom < 4096 ? denom : 4096;
        for (long n = 0; n <= limit; n++) {
            emit((float)n / (float)denom);
        }
    }

    /* 2. Values whose 7th significant digit is a 5 with nothing after it: exact
     *    decimal ties, where the kept digit's parity decides the answer. */
    for (long n = 1; n < 20000; n++) {
        emit((float)n / 128.0f);
        emit((float)n / 256.0f);
        emit((float)n / 512.0f);
        emit((float)n / 1024.0f);
        emit((float)n / 2048.0f);
    }

