        999998.5f, 999999.0f, 999999.4f, 999999.5f, 999999.6f, 1e6f, 1000001.0f,
        1234567.0f, 12345678.0f, 0.1f, 0.5f, 1.0f / 3.0f, 2.0f / 3.0f,
        1e-45f, 1.4e-45f, FLT_MIN, FLT_MAX, FLT_EPSILON, 1e38f, -1e38f,
        1e-38f, 1e-39f, 1e-40f, 16777216.0f, 16777217.0f, 8388608.5f,
        0.0001220703125f, 1.5e-7f, -0.6875f, 1e7f, 1e-6f, 123456.0f, 1234560.0f,
