/// Resolve the element count from the command line.
///
/// Any failure here is a C++ exception escaping `main`, which does not return: it
/// prints libstdc++'s terminate message and aborts.
fn parse_count(argv: &[Vec<u8>]) -> i32 {
    if argv.len() <= 1 || argv[1].as_slice() != COUNT_FLAG {
        return DEFAULT_COUNT;
    }

    match argv.get(2) {
        Some(text) => match stoi::stoi(text) {
            Ok(count) => count,
            Err(error) => {
                terminate::terminate_after_uncaught_exception(error.exception_type(), error.what())
            }
        },
