    fn larger_counts() {
        assert_eq!(output(1000), "0.488281 0.488281\n");
        assert_eq!(output(1024), "0.5 0.5\n");
        assert_eq!(output(1025), "0.500488 0.250244\n");
        assert_eq!(output(10000), "0.610352 0.305176\n");
        assert_eq!(output(100000), "0.762939 0.38147\n");
    }
}

