/// The doubling factor, `GrowthFactor` in the C++ template.
pub const GROWTH_FACTOR: usize = 2;

/// The largest representable bucket count, i.e. `max_bucket_count()`.
///
/// The C++ policy throws `std::length_error` when asked for more than this.
/// Nothing in this program can get near it — every bucket has to be allocated —
/// but asking for it must fail loudly rather than shift past the width of a
/// `usize`.
pub const MAX_BUCKET_COUNT: usize = 1usize << (usize::BITS - 1);

#[derive(Clone, Copy, Debug)]
pub struct PowerOfTwoGrowthPolicy {
    mask: usize,
}

impl PowerOfTwoGrowthPolicy {
    /// Build a policy for at least `min_bucket_count` buckets, returning the
    /// rounded-up count alongside it.
    ///
    /// This mirrors the C++ constructor's in/out parameter, which rewrites the
    /// caller's requested bucket count to the power of two actually used.
    ///
    /// # Panics
    /// If `min_bucket_count` exceeds [`MAX_BUCKET_COUNT`], where the C++
    /// constructor throws `std::length_error`.
    pub fn new(min_bucket_count: usize) -> (Self, usize) {
        assert!(
            min_bucket_count <= MAX_BUCKET_COUNT,
            "requested bucket count {min_bucket_count} exceeds the maximum of {MAX_BUCKET_COUNT}"
        );
        if min_bucket_count == 0 {
            return (PowerOfTwoGrowthPolicy { mask: 0 }, 0);
        }
        let bucket_count = round_up_to_power_of_two(min_bucket_count);
        (
            PowerOfTwoGrowthPolicy {
                mask: bucket_count - 1,
            },
            bucket_count,
        )
    }

    /// The bucket a hash belongs to.
    pub fn bucket_for_hash(&self, hash: u64) -> usize {
        (hash as usize) & self.mask
    }

    /// The bucket count to grow to. From a count of 0 this yields 2.
    ///
    /// # Panics
    /// If the doubled count would exceed [`MAX_BUCKET_COUNT`], where the C++
    /// policy throws `std::length_error`.
    pub fn next_bucket_count(&self) -> usize {
        let current = self.mask + 1;
        assert!(
            current <= MAX_BUCKET_COUNT / GROWTH_FACTOR,
            "bucket count {current} cannot grow any further"
        );
        current * GROWTH_FACTOR
    }
}

/// Smallest power of two `>= value`, with 0 and 1 both mapping to 1.
///
/// # Panics
/// If `value` exceeds [`MAX_BUCKET_COUNT`], the largest power of two a `usize`
/// can hold.
pub fn round_up_to_power_of_two(value: usize) -> usize {
    assert!(
        value <= MAX_BUCKET_COUNT,
        "{value} has no power of two above it that fits a usize"
    );
    if value <= 1 {
        return 1;
    }
    // `value - 1` is neither 0 nor >= MAX_BUCKET_COUNT, so the shift stays in
    // range.
    1usize << (usize::BITS - (value - 1).leading_zeros())
}

