#![allow(dead_code)]

//! The bucket-count growth policy.
//!
//! `tsl::hopscotch_map` defaults to `tsl::hh::power_of_two_growth_policy<2>`:
//! bucket counts are powers of two so a hash maps to a bucket with a mask
//! instead of a modulo, and growing doubles the count.
//!
//! The one wrinkle worth spelling out: a policy built from a bucket count of 0
//! keeps a mask of 0, and the next bucket count is computed as
//! `(mask + 1) * GROWTH_FACTOR`. So the very first growth of a default-constructed
//! map goes from 0 straight to 2, never to 1. Every bucket count this program
//! ever sees follows from that: 0, 2, 4, 8, 16, ...

/// The doubling factor, `GrowthFactor` in the C++ template.
pub const GROWTH_FACTOR: usize = 2;

#[derive(Clone, Copy, Debug)]
pub struct PowerOfTwoGrowthPolicy {
    mask: usize,
}

impl PowerOfTwoGrowthPolicy {
    /// Build a policy for at least `min_bucket_count` buckets, returning the
    /// rounded-up count alongside it.
    ///
    /// This mirrors the C++ constructor's in/out parameter, which rewrites the
    /// caller's requested bucket count to the power of two actually used.
    pub fn new(min_bucket_count: usize) -> (Self, usize) {
        if min_bucket_count == 0 {
            return (PowerOfTwoGrowthPolicy { mask: 0 }, 0);
        }
        let bucket_count = round_up_to_power_of_two(min_bucket_count);
        (
            PowerOfTwoGrowthPolicy {
                mask: bucket_count - 1,
            },
            bucket_count,
        )
    }

    /// The bucket a hash belongs to.
    pub fn bucket_for_hash(&self, hash: u64) -> usize {
        (hash as usize) & self.mask
    }

    /// The bucket count to grow to. From a count of 0 this yields 2.
    pub fn next_bucket_count(&self) -> usize {
        (self.mask + 1) * GROWTH_FACTOR
    }
}

/// Smallest power of two `>= value`, with 0 and 1 both mapping to 1.
pub fn round_up_to_power_of_two(value: usize) -> usize {
    if value <= 1 {
        return 1;
    }
    // `value - 1` cannot be 0 here, so leading_zeros() < usize::BITS.
    1usize << (usize::BITS - (value - 1).leading_zeros())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rounding_up() {
        assert_eq!(round_up_to_power_of_two(0), 1);
        assert_eq!(round_up_to_power_of_two(1), 1);
        assert_eq!(round_up_to_power_of_two(2), 2);
        assert_eq!(round_up_to_power_of_two(3), 4);
        assert_eq!(round_up_to_power_of_two(22), 32);
        assert_eq!(round_up_to_power_of_two(1024), 1024);
        assert_eq!(round_up_to_power_of_two(1025), 2048);
        assert_eq!(round_up_to_power_of_two(200_000), 262_144);
    }

    #[test]
    fn an_empty_policy_grows_to_two() {
        let (policy, count) = PowerOfTwoGrowthPolicy::new(0);
        assert_eq!(count, 0);
        assert_eq!(policy.next_bucket_count(), 2);
    }

    #[test]
    fn growth_doubles() {
        let (policy, count) = PowerOfTwoGrowthPolicy::new(5);
        assert_eq!(count, 8);
        assert_eq!(policy.next_bucket_count(), 16);
    }

    #[test]
    fn masking_selects_the_low_bits() {
        let (policy, _) = PowerOfTwoGrowthPolicy::new(16);
        assert_eq!(policy.bucket_for_hash(0), 0);
        assert_eq!(policy.bucket_for_hash(17), 1);
        assert_eq!(policy.bucket_for_hash(u64::MAX), 15);
    }
}

